/**
 * pdv-movimentacao — API HTTP de Movimentação de Caixas QR para PDV de Terceiros
 *
 * Expõe operações de consulta, entrada e saída de caixas (etiquetas QR) para
 * PDVs externos, preservando paridade total com o scanner interno (bipar_lote_scanner).
 *
 * Auth: header x-api-key validado via RPC validar_pdv_api_key (bcrypt, escopo por loja).
 * Sem JWT: verify_jwt = false no config.toml (auth é por API key própria).
 *
 * Endpoints:
 *   GET  /pdv-movimentacao/etiqueta/:uid  → consultar_etiqueta_pdv (R1/A1)
 *   POST /pdv-movimentacao/entrada        → movimentar_lote_pdv tipo=entrada (R2/A2)
 *   POST /pdv-movimentacao/saida          → movimentar_lote_pdv tipo=saida (R3/A3)
 *
 * Body POST: { loja_id: integer, uids: string[] }  (cap 500 UIDs por request)
 *
 * Spec: .harness/spec/pdv-recebimento-externo/spec.md
 * ADR:  .harness/memory-bank/decisions/ADR-20260625-pdv-movimentacao-externa.md
 */

import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

// ─── Constantes ──────────────────────────────────────────────────────────────

const MAX_UIDS_PER_REQUEST = 500

const CORS_HEADERS: Record<string, string> = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers':
    'authorization, x-client-info, apikey, content-type, x-api-key',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
}

// ─── Tipos ───────────────────────────────────────────────────────────────────

type BatchBodyOk = { ok: true; loja_id: number; uids: string[] }
type BatchBodyError = { ok: false; error: string; message: string; httpStatus: number }
type BatchBodyResult = BatchBodyOk | BatchBodyError

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Resposta JSON com headers CORS e Content-Type corretos. */
function json(data: unknown, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...CORS_HEADERS, 'Content-Type': 'application/json' },
  })
}

/**
 * Extrai rota e params do path após o nome da função.
 * Exemplo: /functions/v1/pdv-movimentacao/etiqueta/ABC → { route: 'etiqueta', params: ['ABC'] }
 * Exportada para testabilidade (testes sem rede).
 */
export function parseRoute(url: URL): { route: string; params: string[] } {
  const parts = url.pathname.split('/').filter(Boolean)
  const funcIdx = parts.findIndex((p) => p === 'pdv-movimentacao')
  const routeParts = funcIdx >= 0 ? parts.slice(funcIdx + 1) : []
  return {
    route: routeParts[0] ?? '',
    params: routeParts.slice(1),
  }
}

/**
 * Valida o body de uma requisição de entrada/saída.
 * Exportada para testabilidade (testes sem rede).
 */
export function validateBatchBody(body: unknown): BatchBodyResult {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    return {
      ok: false,
      error: 'invalid_body',
      message: 'Corpo JSON deve ser um objeto com loja_id e uids',
      httpStatus: 400,
    }
  }

  const b = body as Record<string, unknown>

  if (typeof b.loja_id !== 'number' || !Number.isInteger(b.loja_id)) {
    return {
      ok: false,
      error: 'loja_id_required',
      message: 'loja_id é obrigatório e deve ser um número inteiro',
      httpStatus: 400,
    }
  }

  if (!Array.isArray(b.uids) || b.uids.length === 0) {
    return {
      ok: false,
      error: 'uids_required',
      message: 'uids deve ser um array não-vazio de strings (UIDs de etiquetas)',
      httpStatus: 400,
    }
  }

  if (b.uids.length > MAX_UIDS_PER_REQUEST) {
    return {
      ok: false,
      error: 'too_many_uids',
      message: `Máximo ${MAX_UIDS_PER_REQUEST} UIDs por requisição`,
      httpStatus: 422,
    }
  }

  return {
    ok: true,
    loja_id: b.loja_id,
    uids: b.uids as string[],
  }
}

// ─── Handler principal (exportado para testes) ────────────────────────────────

/**
 * Handler desacoplado do serve() para permitir testes unitários sem rede.
 * O supabase client é injetado externamente (real ou mock).
 */
export async function handler(
  req: Request,
  // deno-lint-ignore no-explicit-any
  supabase: any,
): Promise<Response> {
  // ── Auth: header x-api-key obrigatório ────────────────────────────────────
  const apiKey = req.headers.get('x-api-key')
  if (!apiKey) {
    return json(
      { error: 'missing_api_key', message: 'Header x-api-key obrigatório' },
      401,
    )
  }

  // ── Validar API key via RPC (bcrypt, timing-safe) ──────────────────────────
  const { data: valResult, error: valError } = await supabase.rpc(
    'validar_pdv_api_key',
    { p_key: apiKey },
  )

  if (valError || !valResult?.ok) {
    return json(
      { error: 'unauthorized', message: 'API key inválida, inativa ou revogada' },
      401,
    )
  }

  const apiKeyId: string = valResult.api_key_id
  const lojaIds: number[] = (valResult.loja_ids ?? []) as number[]

  // ── Roteamento ─────────────────────────────────────────────────────────────
  const url = new URL(req.url)
  const { route, params } = parseRoute(url)

  // GET /etiqueta/:uid ─────────────────────────────────────────────────────
  if (req.method === 'GET' && route === 'etiqueta') {
    const uid = params[0]
    if (!uid) {
      return json(
        { error: 'uid_required', message: 'UID obrigatório no path: /etiqueta/{uid}' },
        400,
      )
    }

    const { data, error } = await supabase.rpc('consultar_etiqueta_pdv', {
      p_uid: uid,
    })

    if (error) {
      return json({ error: 'rpc_error', message: error.message }, 500)
    }

    if (!data?.ok) {
      return json(
        { error: 'not_found', message: 'Etiqueta não encontrada', uid },
        404,
      )
    }

    return json(data)
  }

  // POST /entrada ou POST /saida ────────────────────────────────────────────
  if ((route === 'entrada' || route === 'saida') && req.method === 'POST') {
    // Parse body
    let body: unknown
    try {
      body = await req.json()
    } catch {
      return json(
        { error: 'invalid_json', message: 'Corpo deve ser JSON válido' },
        400,
      )
    }

    // Validar corpo
    const validated = validateBatchBody(body)
    if (!validated.ok) {
      return json(
        { error: validated.error, message: validated.message },
        validated.httpStatus,
      )
    }

    const { loja_id, uids } = validated

    // Validar escopo de loja (R6/A6)
    if (!lojaIds.includes(loja_id)) {
      return json(
        {
          error: 'loja_fora_escopo',
          message: `Loja ${loja_id} não está no escopo desta chave`,
          loja_ids_permitidos: lojaIds,
        },
        403,
      )
    }

    // Executar batch via RPC
    const { data, error } = await supabase.rpc('movimentar_lote_pdv', {
      p_loja_id: loja_id,
      p_uids: uids,
      p_tipo: route,         // 'entrada' | 'saida'
      p_api_key_id: apiKeyId,
    })

    if (error) {
      return json({ error: 'rpc_error', message: error.message }, 500)
    }

    return json(data)
  }

  // Rota não encontrada
  return json(
    {
      error: 'not_found',
      message: `Rota não encontrada: ${req.method} ${url.pathname}`,
      rotas_validas: [
        'GET  /pdv-movimentacao/etiqueta/:uid',
        'POST /pdv-movimentacao/entrada',
        'POST /pdv-movimentacao/saida',
      ],
    },
    404,
  )
}

// ─── Bootstrap ───────────────────────────────────────────────────────────────

const SUPABASE_URL = Deno.env.get('SUPABASE_URL') ?? ''
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''

serve(async (req: Request) => {
  // OPTIONS pre-flight (CORS)
  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: CORS_HEADERS })
  }

  // Service role client — bypassa RLS (segurança via RPC SECURITY DEFINER)
  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY)

  return handler(req, supabase)
})

/**
 * Testes smoke — pdv-movimentacao edge function
 *
 * Sem rede: testa lógica de roteamento e validação em funções puras (parseRoute,
 * validateBatchBody) + testa o handler com mock de supabase client.
 *
 * Rodar: deno test supabase/functions/pdv-movimentacao/
 *   (ou: deno test --allow-env supabase/functions/pdv-movimentacao/index.test.ts)
 *
 * O mock do supabase NÃO faz chamadas de rede — apenas retorna dados estáticos
 * para simular o comportamento das RPCs.
 */

import { assertEquals } from 'https://deno.land/std@0.224.0/assert/mod.ts'
import { parseRoute, validateBatchBody, handler } from './index.ts'

// ════════════════════════════════════════════════════════════════
// parseRoute — extração de rota e params do URL
// ════════════════════════════════════════════════════════════════

Deno.test('parseRoute: GET /etiqueta/ABC → route=etiqueta, params=[ABC]', () => {
  const url = new URL(
    'https://jaumyfyeueayibbxunxc.supabase.co/functions/v1/pdv-movimentacao/etiqueta/ABC123',
  )
  const { route, params } = parseRoute(url)
  assertEquals(route, 'etiqueta')
  assertEquals(params, ['ABC123'])
})

Deno.test('parseRoute: POST /entrada → route=entrada, params=[]', () => {
  const url = new URL(
    'https://jaumyfyeueayibbxunxc.supabase.co/functions/v1/pdv-movimentacao/entrada',
  )
  const { route, params } = parseRoute(url)
  assertEquals(route, 'entrada')
  assertEquals(params, [])
})

Deno.test('parseRoute: POST /saida → route=saida, params=[]', () => {
  const url = new URL(
    'https://jaumyfyeueayibbxunxc.supabase.co/functions/v1/pdv-movimentacao/saida',
  )
  const { route } = parseRoute(url)
  assertEquals(route, 'saida')
})

Deno.test('parseRoute: rota desconhecida /foobar → route=foobar', () => {
  const url = new URL(
    'https://jaumyfyeueayibbxunxc.supabase.co/functions/v1/pdv-movimentacao/foobar',
  )
  const { route } = parseRoute(url)
  assertEquals(route, 'foobar')
})

Deno.test('parseRoute: path sem suffix → route=""', () => {
  const url = new URL(
    'https://jaumyfyeueayibbxunxc.supabase.co/functions/v1/pdv-movimentacao',
  )
  const { route } = parseRoute(url)
  assertEquals(route, '')
})

// ════════════════════════════════════════════════════════════════
// validateBatchBody — validação do corpo POST
// ════════════════════════════════════════════════════════════════

Deno.test('validateBatchBody: corpo válido → ok=true com loja_id e uids', () => {
  const result = validateBatchBody({ loja_id: 2, uids: ['UID-A', 'UID-B'] })
  assertEquals(result.ok, true)
  if (result.ok) {
    assertEquals(result.loja_id, 2)
    assertEquals(result.uids, ['UID-A', 'UID-B'])
  }
})

Deno.test('validateBatchBody: uids vazio [] → ok=false, httpStatus=400', () => {
  const result = validateBatchBody({ loja_id: 2, uids: [] })
  assertEquals(result.ok, false)
  if (!result.ok) {
    assertEquals(result.httpStatus, 400)
    assertEquals(result.error, 'uids_required')
  }
})

Deno.test('validateBatchBody: loja_id ausente → ok=false, httpStatus=400', () => {
  const result = validateBatchBody({ uids: ['UID-A'] })
  assertEquals(result.ok, false)
  if (!result.ok) assertEquals(result.httpStatus, 400)
})

Deno.test('validateBatchBody: loja_id string → ok=false (deve ser inteiro)', () => {
  const result = validateBatchBody({ loja_id: '2', uids: ['UID-A'] })
  assertEquals(result.ok, false)
  if (!result.ok) assertEquals(result.httpStatus, 400)
})

Deno.test('validateBatchBody: loja_id float → ok=false (deve ser inteiro)', () => {
  const result = validateBatchBody({ loja_id: 2.5, uids: ['UID-A'] })
  assertEquals(result.ok, false)
  if (!result.ok) assertEquals(result.httpStatus, 400)
})

Deno.test('validateBatchBody: 500 uids → ok=true (limite exato permitido)', () => {
  const result = validateBatchBody({ loja_id: 2, uids: Array(500).fill('U') })
  assertEquals(result.ok, true)
})

Deno.test('validateBatchBody: 501 uids → ok=false, httpStatus=422', () => {
  const result = validateBatchBody({ loja_id: 2, uids: Array(501).fill('U') })
  assertEquals(result.ok, false)
  if (!result.ok) {
    assertEquals(result.httpStatus, 422)
    assertEquals(result.error, 'too_many_uids')
  }
})

Deno.test('validateBatchBody: body não-objeto (array) → ok=false, httpStatus=400', () => {
  const result = validateBatchBody([{ loja_id: 2, uids: ['U'] }])
  assertEquals(result.ok, false)
  if (!result.ok) assertEquals(result.httpStatus, 400)
})

Deno.test('validateBatchBody: body null → ok=false, httpStatus=400', () => {
  const result = validateBatchBody(null)
  assertEquals(result.ok, false)
  if (!result.ok) assertEquals(result.httpStatus, 400)
})

// ════════════════════════════════════════════════════════════════
// handler — testes com mock de supabase client (sem rede)
// ════════════════════════════════════════════════════════════════

/** Mock de supabase que retorna a chave como válida para as RPCs. */
// deno-lint-ignore no-explicit-any
function mockSupabaseValido(lojaIds: number[] = [2, 3]): any {
  return {
    rpc: (name: string) => {
      if (name === 'validar_pdv_api_key') {
        return Promise.resolve({
          data: { ok: true, api_key_id: 'uuid-abc', loja_ids: lojaIds },
          error: null,
        })
      }
      if (name === 'consultar_etiqueta_pdv') {
        return Promise.resolve({
          data: { ok: true, etiqueta: { uid: 'TEST-UID' }, vencido: false },
          error: null,
        })
      }
      if (name === 'movimentar_lote_pdv') {
        return Promise.resolve({
          data: { ok: true, processados: 1, falhas: 0, resultados: [] },
          error: null,
        })
      }
      return Promise.resolve({ data: null, error: null })
    },
  }
}

/** Mock com chave inválida. */
// deno-lint-ignore no-explicit-any
function mockSupabaseInvalido(): any {
  return {
    rpc: () => Promise.resolve({ data: { ok: false }, error: null }),
  }
}

// ── Ausência de x-api-key → 401 ──────────────────────────────────────────────
Deno.test('handler: sem x-api-key → 401 missing_api_key', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/etiqueta/X',
    { method: 'GET' },
  )
  const res = await handler(req, {} as unknown)
  assertEquals(res.status, 401)
  const body = await res.json()
  assertEquals(body.error, 'missing_api_key')
})

// ── API key inválida → 401 unauthorized ──────────────────────────────────────
Deno.test('handler: api-key inválida → 401 unauthorized', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/entrada',
    {
      method: 'POST',
      headers: { 'x-api-key': 'pdvk_invalida', 'Content-Type': 'application/json' },
      body: JSON.stringify({ loja_id: 2, uids: ['A'] }),
    },
  )
  const res = await handler(req, mockSupabaseInvalido())
  assertEquals(res.status, 401)
  const body = await res.json()
  assertEquals(body.error, 'unauthorized')
})

// ── Rota desconhecida → 404 ───────────────────────────────────────────────────
Deno.test('handler: GET /foobar → 404 not_found', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/foobar',
    { method: 'GET', headers: { 'x-api-key': 'pdvk_teste' } },
  )
  const res = await handler(req, mockSupabaseValido())
  assertEquals(res.status, 404)
  const body = await res.json()
  assertEquals(body.error, 'not_found')
})

// ── POST /entrada com loja fora do escopo → 403 ───────────────────────────────
Deno.test('handler: loja 99 fora do escopo [2,3] → 403 loja_fora_escopo', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/entrada',
    {
      method: 'POST',
      headers: { 'x-api-key': 'pdvk_teste', 'Content-Type': 'application/json' },
      body: JSON.stringify({ loja_id: 99, uids: ['UID-A'] }),
    },
  )
  const res = await handler(req, mockSupabaseValido([2, 3]))
  assertEquals(res.status, 403)
  const body = await res.json()
  assertEquals(body.error, 'loja_fora_escopo')
})

// ── POST /entrada com uids vazio → 400 ───────────────────────────────────────
Deno.test('handler: POST /entrada com uids=[] → 400 uids_required', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/entrada',
    {
      method: 'POST',
      headers: { 'x-api-key': 'pdvk_teste', 'Content-Type': 'application/json' },
      body: JSON.stringify({ loja_id: 2, uids: [] }),
    },
  )
  // Validação de body ocorre ANTES de chamar movimentar_lote_pdv,
  // então o mock só precisa responder a validar_pdv_api_key.
  const res = await handler(req, mockSupabaseValido([2]))
  assertEquals(res.status, 400)
  const body = await res.json()
  assertEquals(body.error, 'uids_required')
})

// ── GET /etiqueta/:uid → 200 com dados da etiqueta ───────────────────────────
Deno.test('handler: GET /etiqueta/TEST-UID → 200 com etiqueta', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/etiqueta/TEST-UID',
    { method: 'GET', headers: { 'x-api-key': 'pdvk_teste' } },
  )
  const res = await handler(req, mockSupabaseValido())
  assertEquals(res.status, 200)
  const body = await res.json()
  assertEquals(body.ok, true)
})

// ── GET /etiqueta sem uid → 400 ───────────────────────────────────────────────
Deno.test('handler: GET /etiqueta sem uid no path → 400 uid_required', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/etiqueta',
    { method: 'GET', headers: { 'x-api-key': 'pdvk_teste' } },
  )
  const res = await handler(req, mockSupabaseValido())
  assertEquals(res.status, 400)
  const body = await res.json()
  assertEquals(body.error, 'uid_required')
})

// ── POST /saida válido → 200 ──────────────────────────────────────────────────
Deno.test('handler: POST /saida válido → 200 com resultado batch', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/saida',
    {
      method: 'POST',
      headers: { 'x-api-key': 'pdvk_teste', 'Content-Type': 'application/json' },
      body: JSON.stringify({ loja_id: 2, uids: ['UID-X'] }),
    },
  )
  const res = await handler(req, mockSupabaseValido([2]))
  assertEquals(res.status, 200)
  const body = await res.json()
  assertEquals(body.ok, true)
})

// ── POST com JSON inválido → 400 ─────────────────────────────────────────────
Deno.test('handler: POST /entrada com JSON malformado → 400 invalid_json', async () => {
  const req = new Request(
    'https://proj.supabase.co/functions/v1/pdv-movimentacao/entrada',
    {
      method: 'POST',
      headers: { 'x-api-key': 'pdvk_teste', 'Content-Type': 'application/json' },
      body: 'nao-e-json{{{',
    },
  )
  const res = await handler(req, mockSupabaseValido())
  assertEquals(res.status, 400)
  const body = await res.json()
  assertEquals(body.error, 'invalid_json')
})
